function cleanupJsonString(text) {
  if (typeof text !== "string") return "";

  let cleaned = text
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  const firstBrace = cleaned.indexOf("{");
  if (firstBrace > 0) cleaned = cleaned.slice(firstBrace);

  cleaned = cleaned.replace(/,\s*([}\]])/g, "$1");

  return cleaned;
}

function extractJsonFromText(text) {
  if (typeof text !== "string") return null;

  let candidate = cleanupJsonString(text);

  try {
    return JSON.parse(candidate);
  } catch {}

  for (let i = 0; i < 20; i++) {
    try {
      return JSON.parse(candidate);
    } catch {}

    candidate = candidate.replace(/,\s*([}\]])/g, "$1");

    const quoteCount = (candidate.match(/"/g) || []).length;
    const openBraces = (candidate.match(/{/g) || []).length;
    const closeBraces = (candidate.match(/}/g) || []).length;
    const openBrackets = (candidate.match(/\[/g) || []).length;
    const closeBrackets = (candidate.match(/]/g) || []).length;

    if (quoteCount % 2 !== 0) {
      candidate += '"';
      continue;
    }

    if (openBrackets > closeBrackets) {
      candidate += "]";
      continue;
    }

    if (openBraces > closeBraces) {
      candidate += "}";
      continue;
    }

    break;
  }

  try {
    return JSON.parse(candidate);
  } catch {}

  return null;
}

function clampNumber(value, min = 0, max = 100, fallback = 0) {
  if (typeof value !== "number" || Number.isNaN(value)) return fallback;
  return Math.max(min, Math.min(max, value));
}

function nullablePercent(value) {
  if (value === null) return null;
  if (typeof value !== "number" || Number.isNaN(value)) return null;
  return Math.max(0, Math.min(100, value));
}

function asString(value, fallback = "") {
  return typeof value === "string" ? value : fallback;
}

const SUPPORTED_LANGUAGES = new Set(['fr', 'en', 'es', 'de', 'it', 'pt']);
const DEFAULT_LANGUAGE = 'fr';
const OUTPUT_LANGUAGE_ALIASES = {
  french: 'fr',
  francais: 'fr',
  'français': 'fr',
  english: 'en',
  spanish: 'es',
  espanol: 'es',
  'español': 'es',
  german: 'de',
  deutsch: 'de',
  italian: 'it',
  italiano: 'it',
  portuguese: 'pt',
  portugues: 'pt',
  'português': 'pt',
};

function normalizeLanguageCandidate(value) {
  if (typeof value !== "string") return null;

  const normalized = value.trim().toLowerCase();
  if (!normalized) return null;

  const alias = OUTPUT_LANGUAGE_ALIASES[normalized];
  if (alias) return alias;

  const [baseLocale] = normalized.split(/[-_]/);
  return SUPPORTED_LANGUAGES.has(baseLocale) ? baseLocale : null;
}

function normalizeWorkflowLanguageFromCandidates(...values) {
  for (const value of values) {
    const normalized = normalizeLanguageCandidate(value);
    if (normalized) return normalized;
  }

  return DEFAULT_LANGUAGE;
}

function getNodeLanguage(nodeName) {
  try {
    return $(nodeName).first().json.language;
  } catch (e) {
    return undefined;
  }
}

function getLocalizedFallbacks(lang) {
  switch (lang) {
    case "fr":
