      };
  }
}

function normalizeArea(area) {
  return {
    area_name: asString(area?.area_name),
    subcutaneous_fat_percent: clampNumber(area?.subcutaneous_fat_percent),
    water_retention_percent: clampNumber(area?.water_retention_percent),
    definition_percent: clampNumber(area?.definition_percent),
    dominant_type: asString(area?.dominant_type),
    confidence: clampNumber(area?.confidence),
    explanation: asString(area?.explanation),
    actionable_advice: asString(area?.actionable_advice)
  };
}

function collectTextCandidates(obj) {
  const out = [];

  function visit(value) {
    if (value == null) return;

    if (typeof value === "string") {
      out.push(value);
      return;
    }

    if (Array.isArray(value)) {
      for (const item of value) visit(item);
      return;
    }

    if (typeof value === "object") {
      if (typeof value.text === "string") out.push(value.text);
      if (typeof value.content === "string") out.push(value.content);
      if (typeof value.output === "string") out.push(value.output);
      if (typeof value.response === "string") out.push(value.response);

      for (const key of Object.keys(value)) {
        visit(value[key]);
      }
    }
  }

  visit(obj);
  return out.filter(Boolean);
}

const userLanguage = normalizeWorkflowLanguageFromCandidates(
  getNodeLanguage('Code in JavaScript3'),
  getNodeLanguage('Code in JavaScript1'),
  $json.language,
  $json.locale,
  $json.outputLanguage,
  $json.body?.language,
  $json.body?.locale,
  $json.body?.outputLanguage
);
const messages = getLocalizedFallbacks(userLanguage);

const j = $input.item.json || $json;

const textCandidates = collectTextCandidates(j);
const objectCandidates = [j, j?.data, j?.response, j?.output].filter(
  (v) => v && typeof v === "object"
);

let rawObj = null;

for (const obj of objectCandidates) {
  if (obj?.scan_type) {
    rawObj = obj;
    break;
  }
  if (obj?.data && typeof obj.data === "object" && obj.data?.scan_type) {
    rawObj = obj.data;
    break;
  }
}

if (!rawObj) {
  for (const text of textCandidates) {
    const parsed = extractJsonFromText(text);
    if (parsed && typeof parsed === "object") {
      rawObj =
        parsed?.data && typeof parsed.data === "object"
          ? parsed.data
          : parsed;

      if (rawObj?.scan_type) break;
    }
  }
}

if (!rawObj || typeof rawObj !== "object") {
  return [{
    json: {
      success: false,
      error: messages.invalidFormat,
      raw_output: textCandidates[0] || JSON.stringify(j)
    }
  }];
}

if (rawObj.scan_type === "error") {
  return [{
    json: {
      success: false,
      error: asString(rawObj.message, messages.genericError),
      data: {
        scan_type: "error",
        message: asString(rawObj.message, messages.genericError)
      }
    }
  }];
}

const finalData = {
  scan_type: "fat_distribution_scan_v2",
  global_body_fat_estimate_percent: nullablePercent(rawObj.global_body_fat_estimate_percent),
  global_facial_fat_estimate_percent: nullablePercent(rawObj.global_facial_fat_estimate_percent),
  global_water_retention_estimate_percent: clampNumber(
    rawObj.global_water_retention_estimate_percent,
    0,
    100,
    0
  ),
  analysis_summary: asString(rawObj.analysis_summary),
  dominant_storage_pattern: asString(rawObj.dominant_storage_pattern),
  areas_analysis: Array.isArray(rawObj.areas_analysis)
    ? rawObj.areas_analysis.map(normalizeArea)
    : [],
  priority_zones: Array.isArray(rawObj.priority_zones)
    ? rawObj.priority_zones.map((z) => asString(z)).filter(Boolean)
    : [],
  disclaimer_text: asString(rawObj.disclaimer_text, messages.fallbackDisclaimer)
};

return [{
  json: {
    success: true,
    data: finalData
  }
}];

const item = $input.item;
let base64Data = item.json.body?.imageBase64 || '';

const SUPPORTED_LANGUAGES = new Set(['fr', 'en', 'es', 'de', 'it', 'pt']);
const DEFAULT_LANGUAGE = 'fr';
const OUTPUT_LANGUAGE_BY_CODE = {
  fr: 'French',
  en: 'English',
  es: 'Spanish',
  de: 'German',
  it: 'Italian',
  pt: 'Portuguese',
};
const OUTPUT_LANGUAGE_ALIASES = {
  french: 'fr',
  francais: 'fr',
  'français': 'fr',
  english: 'en',
  spanish: 'es',
  espanol: 'es',
  'español': 'es',
  german: 'de',
  deutsch: 'de',
  italian: 'it',
  italiano: 'it',
  portuguese: 'pt',
  portugues: 'pt',
  'português': 'pt',
};

function normalizeLanguageCandidate(value) {
  if (typeof value !== 'string') return null;

  const normalized = value.trim().toLowerCase();
  if (!normalized) return null;

  const alias = OUTPUT_LANGUAGE_ALIASES[normalized];
  if (alias) return alias;

  const [baseLocale] = normalized.split(/[-_]/);
  return SUPPORTED_LANGUAGES.has(baseLocale) ? baseLocale : null;
}

function normalizeWorkflowLanguageFromCandidates(...values) {
  for (const value of values) {
    const normalized = normalizeLanguageCandidate(value);
    if (normalized) return normalized;
  }

  return DEFAULT_LANGUAGE;
}

const userLanguage = normalizeWorkflowLanguageFromCandidates(
  item.json.body?.language,
  item.json.body?.locale,
  item.json.body?.outputLanguage,
  item.json.language,
  item.json.locale,
  item.json.outputLanguage
);
const outputLanguage = OUTPUT_LANGUAGE_BY_CODE[userLanguage];

if (base64Data.includes(',')) {
  base64Data = base64Data.split(',')[1];
}

return {
  json: {
    ...item.json,
    language: userLanguage,
    locale: userLanguage,
    outputLanguage,
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: 'image/jpeg',
      fileName: 'scan.jpg',
    }
  }
};

const TOLERANCE_MS = 5 * 60 * 1000;
const SIGNATURE_PREFIX = 'sha256=';

const first = $input.first();
const headers = (first && first.json && first.json.headers) || (first && first.headers) || {};
const bodyObj = (first && first.json && first.json.body) || (first && first.body) || (first && first.json) || {};
const rawBody = JSON.stringify(bodyObj);

const timestamp = headers['x-webhook-timestamp'] || headers['X-Webhook-Timestamp'];
const signature = headers['x-webhook-signature'] || headers['X-Webhook-Signature'];
const secret = ($env.PHASE2_WEBHOOK_HMAC_SECRET || $env.COACH_WEBHOOK_HMAC_SECRET || '').trim();

if (!secret) {
  throw new Error('PHASE2_WEBHOOK_HMAC_SECRET missing on n8n side');
}
if (!timestamp || !signature) {
  throw new Error('Webhook missing x-webhook-timestamp or x-webhook-signature');
}

// Anti-replay : timestamp dans une fenêtre de 5 min
const tsDate = new Date(String(timestamp));
if (Number.isNaN(tsDate.getTime())) {
  throw new Error('Invalid x-webhook-timestamp format');
}
const drift = Math.abs(Date.now() - tsDate.getTime());
if (drift > TOLERANCE_MS) {
  throw new Error(`Webhook timestamp drift ${drift}ms exceeds tolerance`);
}

// Recalcul de la signature
const textEncoder = new TextEncoder();
function arrayBufferToHex(buffer) {
  return Array.from(new Uint8Array(buffer)).map((value) => value.toString(16).padStart(2, '0')).join('');
}

async function verifyHmac(payload, secret, providedSig) {
  let expectedHex;
  try {
    const crypto = require('crypto');
    expectedHex = crypto.createHmac('sha256', secret).update(payload).digest('hex');
  } catch (nodeError) {
    const subtle = globalThis.crypto && globalThis.crypto.subtle;
    if (!subtle) {
      throw new Error('Neither Node crypto nor Web Crypto is available. ' + nodeError.message);
    }
    const signingKey = await subtle.importKey('raw', textEncoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const signatureBuffer = await subtle.sign('HMAC', signingKey, textEncoder.encode(payload));
    expectedHex = arrayBufferToHex(signatureBuffer);
  }

  const expected = SIGNATURE_PREFIX + expectedHex;

  // Constant-time comparison
  let mismatch = expected.length ^ providedSig.length;
  const maxLength = Math.max(expected.length, providedSig.length);
  for (let index = 0; index < maxLength; index += 1) {
    mismatch |= (expected.charCodeAt(index) || 0) ^ (providedSig.charCodeAt(index) || 0);
  }
  if (mismatch !== 0) {
    throw new Error('Webhook signature mismatch');
  }
}

await verifyHmac(String(timestamp) + '.' + rawBody, secret, String(signature));

const isSmoke = typeof bodyObj._smoke_test === 'string' && bodyObj._smoke_test.startsWith('check_signing_');

return [{
  json: {
    ...$input.first().json,
    _is_smoke_test: isSmoke
  }
}];

const ENFORCE = ($env.COACH_WEBHOOK_HMAC_ENFORCE || '').trim().toLowerCase() === 'true';
const SECRET = ($env.PHASE2_WEBHOOK_HMAC_SECRET || $env.COACH_WEBHOOK_HMAC_SECRET || '').trim();

if (!SECRET) {
  if (ENFORCE) {
    throw new Error('sign_webhook_response_secret_missing');
  }
  console.warn('[sign-webhook-response] HMAC secret not configured (dual-mode, skipping signature)');
  return $input.all();
}

const rawBody = JSON.stringify($input.first().json);
const timestamp = new Date().toISOString();
const payload = timestamp + '.' + rawBody;

const textEncoder = new TextEncoder();
function arrayBufferToHex(buffer) {
  return Array.from(new Uint8Array(buffer)).map((value) => value.toString(16).padStart(2, '0')).join('');
}

async function signResponse(payload, secret) {
  try {
    const crypto = require('crypto');
    return 'sha256=' + crypto.createHmac('sha256', secret).update(payload).digest('hex');
  } catch (nodeError) {
    const subtle = globalThis.crypto && globalThis.crypto.subtle;
    if (!subtle) {
      throw new Error('Neither Node crypto nor Web Crypto is available. ' + nodeError.message);
    }
    const signingKey = await subtle.importKey('raw', textEncoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const signatureBuffer = await subtle.sign('HMAC', signingKey, textEncoder.encode(payload));
    return 'sha256=' + arrayBufferToHex(signatureBuffer);
  }
}

const sig = await signResponse(payload, SECRET);

return [{
  json: {
    body: $input.first().json,
    headers: {
      'x-webhook-response-timestamp': timestamp,
      'x-webhook-response-signature': sig,
    }
  }
}];
